USE bodb02
GO
DECLARE @TransIds			VARCHAR(MAX)
		,@UserId			INT
		,@IP				VARCHAR (50)
		,@ErrCode			INT				= 0		
		,@ErrMsg			VARCHAR(1000)	= ''	
		,@transid_temp		VARCHAR(MAX) = ''
CREATE TABLE #tmpInputTransId (TransId BIGINT)

CREATE TABLE #tmpInputTransId_temp (TransId BIGINT)

SET @TransIds = '107714644441,107714660136,107714663314,107714663345,107714666873,107714727568,107714713727,107714716783,107714718737,107714718762,107714723750,107714761973,107714748572,107714753313,107714756019,107714767752,107714772015,107754468450,107754486436,107754477573,107754481002,107754551134,107754547128,107769177649,107769182460,107769188077,107769190358,107749771879,107749764794,107749766037,107749771879,107749765217,107749765967,107749784375,107749785987,107749802277,107749802729,107749803662,107749843423,107749843870,107749734451,107777864850,107749766768,107749771881,107777921446,107749786326,107777950827,107777951085,107777951252,107777951487,107749804890,107777990839,107749844317,107778103444,107778103636,107778104132,107778104631,107778116581,107714730724,107714735621,107714738819,107714727568,107714713727,107714716783,107714718737,107714718762,107714723750,107714761973,107714748572,107714753313,107714756019,107714767752,107714772015,107754468450,107754486436,107754477573,107754481002,107754551134,107754547128,107769177649,107769182460,107769188077,107769190358,107713295285,107713295697,107713295561,107713295870,107713296703,107713296994,107713297255,107713297473,107713297968,107713298195,107713298482,107713298719,107749276856,107749277029,107749277307,107749277458,107749277862,107749277998,107749278193,107749278455,107749279659,107767911579,107749279849,107767911883,107749279986,107767912226,107749280185,107769082583,107769082859,107769083212,107769083716' 

SET @IP = '125.227.140.97'
SET @UserId = 10278938

INSERT INTO #tmpInputTransId (TransId)
SELECT	DISTINCT val
FROM	dbo.f_SplitString(@TransIds, ',')
ORDER BY val
OPTION (maxrecursion 0)

IF @@ROWCOUNT = 0 RETURN
	
-- Deployer Info
DECLARE @ticket_cnt INT, @index INT = 0
SET @ticket_cnt = (SELECT COUNT(*) FROM #tmpInputTransId )
DECLARE @msg nvarchar(200) = 'Currently at batch %d, tickets: %s.'

WHILE (1 = 1)
BEGIN
	
	DELETE FROM #tmpInputTransId_temp

    DELETE TOP (1000)
    FROM #tmpInputTransId OUTPUT DELETED.TransId INTO #tmpInputTransId_temp
	
	IF @@ROWCOUNT = 0 BREAK
	
	SET @transid_temp = ''
	SET @transid_temp = STUFF((SELECT ',' + CONVERT(VARCHAR(50),transid) FROM #tmpInputTransId_temp FOR XML PATH ('')),1,1,'')
	
	SET @index = @index + 1
	
	RAISERROR (@msg, 0, 1,@index, @transid_temp) WITH NOWAIT
	
	EXEC dbo.TicketVoiding_RecoverHistorical_Single_Update @Transids = @transid_temp, @UserId = @UserId, @IP = @IP, @ErrCode = @ErrCode OUT, @ErrMsg = @ErrMsg OUT
	
	IF @ErrCode <> 0
	BEGIN
		SELECT @ErrCode, @ErrMsg, @transid_temp AS TransIDs
		RETURN
	END
		
	WAITFOR DELAY '00:00:00.280'			
END	

DROP TABLE #tmpInputTransId
DROP TABLE #tmpInputTransId_temp